# MolForge 8.1 修复后 API 冒烟复测（对照审计 RED/YELLOW）
# 用法: pwsh -File smoke_api.ps1   证据: evidence/api_fix/*.json
$ErrorActionPreference = 'Stop'
$base = 'http://127.0.0.1:18765'
$ev = 'E:\YDW\Trae_Chemdraw\docs\desktop\fix_20261120\evidence\api_fix'
New-Item -ItemType Directory -Force -Path $ev | Out-Null
function Post($path, $obj) {
  Invoke-RestMethod -Uri "$base$path" -Method Post -Body ($obj | ConvertTo-Json -Depth 8) -ContentType 'application/json' -TimeoutSec 600
}
function GetJ($path) { Invoke-RestMethod -Uri "$base$path" -TimeoutSec 60 }
function Save($name, $obj) { $obj | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath "$ev\$name.json" -Encoding UTF8 }
$report = @()
function Step($id, $desc, $block) {
  try { $r = & $block; $script:report += [pscustomobject]@{ id=$id; desc=$desc; status='PASS'; detail=$r } }
  catch { $script:report += [pscustomobject]@{ id=$id; desc=$desc; status='FAIL'; detail=$_.Exception.Message } }
}

Step 's01' '基线文档' { $d = GetJ '/api/atoms'; Save 's01_atoms' $d; "atoms=$($d.atoms.Count) bonds=$($d.bonds.Count)" }
Step 's02' 'R11 五砌块在目录' { $f = GetJ '/api/fragments'; Save 's02_fragments' $f; $ids = $f.fragments | ForEach-Object { $_.id }; $need = @('benzene','pentacene','itic','y6','c60'); $miss = $need | Where-Object { $ids -notcontains $_ }; if ($miss) { throw "missing: $miss" }; "all 5 present" }
Step 's03' 'R11 插入苯真坐标' { $a0 = (GetJ '/api/atoms').atoms.Count; $r = Post '/api/edit/insert_fragment' @{ fragment_id='benzene'; attach_to_existing=$false }; $a1 = (GetJ '/api/atoms').atoms.Count; Save 's03_insert_benzene' $r; if ($a1 - $a0 -ne 12) { throw "delta=$($a1-$a0)" }; "12 atoms added" }
Step 's04' 'R8 设键级4=芳香' { $b = (GetJ '/api/atoms').bonds[0]; $r = Post '/api/edit/set_bond_order' @{ bond_id=$b.bond_id; order=4 }; $b2 = (GetJ '/api/atoms').bonds | Where-Object { $_.bond_id -eq $b.bond_id }; Save 's04_set_bond_order' $b2; if (-not $b2.aromatic) { throw 'not aromatic' }; "order=$($b2.order) aromatic=$($b2.aromatic)" }
Step 's05' 'Y6 设原子电荷+撤销' { $r = Post '/api/edit/set_atom_charge' @{ atom_id=0; charge=1 }; $c1 = (GetJ '/api/atoms').atoms[0].formal_charge; Post '/api/edit/undo' @{} | Out-Null; $c0 = (GetJ '/api/atoms').atoms[0].formal_charge; Post '/api/edit/redo' @{} | Out-Null; $c2 = (GetJ '/api/atoms').atoms[0].formal_charge; Post '/api/edit/undo' @{} | Out-Null; Save 's05_charge' @{ set=$c1; undo=$c0; redo=$c2 }; if ($c1 -ne 1 -or $c0 -ne 0 -or $c2 -ne 1) { throw "c=$c1/$c0/$c2" }; "1/0/1 ok" }
Step 's06' 'Y2 2D拖动 pos_2d 对象' { $r = Post '/api/edit/move_atom' @{ id=0; pos_2d=@{ x=5.0; y=5.0 } }; Save 's06_move' $r; $a = (GetJ '/api/atoms').atoms[0]; if ([math]::Abs($a.x2-5) -gt 1e-6) { throw "x2=$($a.x2)" }; "x2=$($a.x2)" }
Step 's07' 'R7 delete_atoms ids 真删+撤销' { $ats = (GetJ '/api/atoms').atoms; $n0 = $ats.Count; $last = $ats[-1].atom_id; Post '/api/edit/delete_atoms' @{ ids=@($last) } | Out-Null; $n1 = (GetJ '/api/atoms').atoms.Count; Post '/api/edit/undo' @{} | Out-Null; $n2 = (GetJ '/api/atoms').atoms.Count; Save 's07_delete' @{ before=$n0; after=$n1; undo=$n2 }; if ($n1 -ne $n0-1 -or $n2 -ne $n0) { throw "$n0/$n1/$n2" }; "$n0->$n1->$n2" }
Step 's08' 'R10 噻吩杂原子+点击位' { $n0 = (GetJ '/api/atoms').atoms.Count; $r = Post '/api/edit/add_ring' @{ size=5; aromatic=$true; hetero=@{ '0'=16 }; center_2d=@{ x=5.0; y=5.0 } }; $ats = (GetJ '/api/atoms').atoms; $new = $ats | Select-Object -Last 5; $s = ($new | Where-Object { $_.atomic_num -eq 16 }).Count; Save 's08_thiophene' $r; if ($s -ne 1) { throw "S count=$s" }; $cx = ($new | Measure-Object -Property x2 -Average).Average; if ([math]::Abs($cx-5) -gt 1.5) { throw "cx=$cx" }; "1 S, center~5" }
Step 's09' 'Y3 xtb/orca 输入导出' { $x = Post '/api/qc/export_input' @{ kind='xtb' }; $o = Post '/api/qc/export_input' @{ kind='orca' }; Save 's09_xtb_input' $x; Save 's09_orca_input' $o; if ($x.content -notmatch 'xtb input.xyz') { throw 'xtb header missing' }; if ($o.content -notmatch '!') { throw 'orca route missing' }; "xtb+orca ok" }
Step 's10' 'R9 CalChem 真 SCF' { Post '/api/build/preset' @{ id='caffeine' } | Out-Null; Start-Sleep -Milliseconds 500; $r = Post '/api/qc/run_calchem' @{ mode='sp'; method='HF'; basis='STO-3G' }; Save 's10_calchem' $r; if (-not $r.ok -or $null -eq $r.total_energy_hartree) { throw "ok=$($r.ok) err=$($r.error)" }; "E=$($r.total_energy_hartree)" }
Step 's11' 'Y4 xTB 真能量' { $r = Post '/api/qc/run_xtb' @{ gfn_level=2; apply_geometry=$false }; Save 's11_xtb' $r; if (-not $r.ok -or $null -eq $r.energy_hartree) { throw "ok=$($r.ok) err=$($r.error)" }; "E=$($r.energy_hartree)" }
Step 's12' 'R1 gaussian 真spawn真能量或诚实失败' { $r = Post '/api/qc/run_external' @{ engine='gaussian'; keywords='#p HF/STO-3G' }; Save 's12_gaussian' $r; if ($r.ok -and $null -ne $r.energy_hartree) { "real gaussian success E=$($r.energy_hartree)" } elseif ($r.status -eq 'engine_not_found') { "honest engine_not_found" } elseif ($r.status -eq 'failed' -and (Test-Path (Join-Path $r.workdir 'input.gjf'))) { "real spawn, honest failed exit=$($r.exit_code)" } else { throw "ok=$($r.ok) status=$($r.status) energy=$($r.energy_hartree)" } }
Step 's13' 'R3 Multiwfn 真散点+门禁' { $r = Post '/api/analysis/run' @{ analysis_id='WFN-12' }; Save 's13_wfn12' $r; $pts = $r.result.metrics.total_scatter_points; if (-not $r.ok -or $pts -lt 1000) { throw "ok=$($r.ok) pts=$pts" }; $r2 = Post '/api/analysis/run' @{ analysis_id='WFN-01' }; Save 's13_wfn01_gate' $r2; if ($r2.result.ok) { throw 'WFN-01 should be unavailable' }; "pts=$pts; WFN-01 gated" }
Step 's14' 'R2 后台真算 orca_sp + md_rdf 拒绝' { $jm = Post '/api/jobs/submit' @{ kind='md_rdf'; label='md rdf smoke' }; $mid = $jm.job.job_id; $mst = $null; for ($i=0; $i -lt 20; $i++) { Start-Sleep -Seconds 1; $me = (GetJ '/api/jobs').jobs | Where-Object { $_.job_id -eq $mid }; $mst = $me.status; if ($mst -eq 'completed' -or $mst -eq 'failed') { break } }; Save 's14_mdrdf_job' $me; if ($mst -ne 'failed' -or $me.error -notmatch '适配器') { throw "md_rdf status=$mst err=$($me.error)" }; Post '/api/build/preset' @{ id='caffeine' } | Out-Null; Start-Sleep -Milliseconds 500; $j = Post '/api/jobs/submit' @{ kind='orca_sp'; label='ORCA HF/STO-3G smoke'; params=@{ keywords='! HF STO-3G' } }; $jid = $j.job.job_id; $st = $null; for ($i=0; $i -lt 80; $i++) { Start-Sleep -Seconds 3; $me = (GetJ '/api/jobs').jobs | Where-Object { $_.job_id -eq $jid }; $st = $me.status; if ($st -eq 'completed' -or $st -eq 'failed') { break } }; Save 's14_orca_job' $me; if ($st -ne 'completed') { throw "status=$st err=$($me.error)" }; "md_rdf failed honest; orca completed" }
Step 's15' 'R6 AI 离线显式标注' { $r = Post '/api/ai/chat' @{ prompt='你好，请介绍当前分子' }; Save 's15_ai_chat' $r; if (-not $r.offline) { throw 'offline flag missing' }; if ($r.reply -notmatch '离线降级') { throw 'prefix missing' }; "offline+prefix ok" }
Step 's16' 'Y9 md-rdf 规划 blocked' { $r = Post '/api/ai/plan_workflow' @{ query='对当前体系做分子动力学径向分布函数 RDF 分析' }; Save 's16_plan_mdrdf' $r; $p = $r.proposal; if ($p.runnable -eq $true) { throw 'proposal runnable despite missing adapter' }; if (-not ($p.missing_dependencies -join ' ') -match 'rdf') { throw 'missing_dependencies lacks rdf' }; "runnable=$($p.runnable); missing=$($p.missing_dependencies -join ';')" }

$report | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath "$ev\smoke_report.json" -Encoding UTF8
$report | ForEach-Object { "{0} {1} {2} :: {3}" -f $_.id, $_.status, $_.desc, $_.detail }